import AppKit
import Lottie
import SwiftUI

/// What Kip should be doing. The view works out the smooth route there (see `KipHostView`).
enum KipState { case sleep, awake, cheer }

struct KipView: View {
    let state: KipState
    var body: some View { KipRepresentable(state: state) }
}

/// Frame ranges inside kip.json. Every boundary between segments is a matching "home" pose, so playback can flow
/// from one segment straight into the next with no visible cut (generated by Scripts/make-lottie.py).
private enum Frames {
    static let sleep: ClosedRange<CGFloat> = 0...75         // loop    : asleep
    static let wakeEnd: CGFloat = 150                       // 75-150  : yawn, stretch, cap flick, eyes open
    static let idle: ClosedRange<CGFloat> = 150...240       // loop    : awake
    static let cheerInEnd: CGFloat = 264                    // 240-264 : arms up, happy face
    static let cheer: ClosedRange<CGFloat> = 264...324      // loop    : cheering
}

/// One Lottie view for Kip's whole life. A small state machine moves between segments:
///  - sleep -> awake/cheer : finish the current breath, then play through the wake-up and into the idle loop
///  - awake -> cheer       : play on to the end of the current idle loop, then straight into the cheer-in
/// Because the segments share home poses, there are no pops, and the view is never swapped or reloaded.
final class KipHostView: NSView {
    private enum Phase { case sleeping, waking, idle, cheerIn, cheering }

    private let lottie = LottieAnimationView()
    private var phase: Phase
    private var target: KipState
    private var started = false

    init(state: KipState) {
        target = state
        phase = state == .sleep ? .sleeping : (state == .awake ? .idle : .cheering)
        super.init(frame: NSRect(x: 0, y: 0, width: 72, height: 72))
        wantsLayer = true
        lottie.contentMode = .scaleAspectFit
        lottie.isHidden = true                       // nothing is drawn until the first real layout
        if let url = Bundle.main.url(forResource: "kip", withExtension: "json") {
            lottie.animation = LottieAnimation.filepath(url.path)
        }
        addSubview(lottie)
    }
    required init?(coder: NSCoder) { fatalError() }

    override func layout() {
        super.layout()
        lottie.frame = bounds
        guard !started, bounds.width >= 16, bounds.height >= 16 else { return }
        started = true                               // first real size: now it is safe to start
        lottie.layoutSubtreeIfNeeded()
        lottie.isHidden = false
        switch phase {
        case .sleeping: loop(Frames.sleep)
        case .idle:     loop(Frames.idle)
        default:        loop(Frames.cheer)
        }
        advance()
    }

    func set(_ state: KipState) {
        guard state != target else { return }
        target = state
        if started { advance() }
    }

    private func loop(_ r: ClosedRange<CGFloat>) {
        if NSWorkspace.shared.accessibilityDisplayShouldReduceMotion { lottie.currentFrame = r.lowerBound; return }   // still pose
        lottie.play(fromFrame: r.lowerBound, toFrame: r.upperBound, loopMode: .loop, completion: nil)
    }

    private func advance() {
        guard !NSWorkspace.shared.accessibilityDisplayShouldReduceMotion else {
            lottie.currentFrame = target == .sleep ? Frames.sleep.lowerBound : (target == .awake ? Frames.idle.lowerBound : Frames.cheer.lowerBound)
            return
        }
        switch (phase, target) {
        case (.sleeping, .awake), (.sleeping, .cheer):
            phase = .waking                           // run on from this breath, through the loop's end, into the wake-up
            lottie.play(fromFrame: lottie.currentFrame, toFrame: Frames.wakeEnd, loopMode: .playOnce) { [weak self] done in
                guard done, let self else { return }
                self.phase = .idle
                if self.target == .awake { self.loop(Frames.idle) } else { self.advance() }
            }
        case (.idle, .cheer):
            phase = .cheerIn                          // same home pose at both ends of the idle loop, so jump in anywhere it passes
            let f = lottie.currentFrame
            let from: CGFloat = f <= Frames.idle.lowerBound + 1 ? Frames.idle.upperBound : f
            lottie.play(fromFrame: from, toFrame: Frames.cheerInEnd, loopMode: .playOnce) { [weak self] done in
                guard done, let self else { return }
                self.phase = .cheering
                self.loop(Frames.cheer)
            }
        default:
            break
        }
    }
}

private struct KipRepresentable: NSViewRepresentable {
    let state: KipState
    func makeNSView(context: Context) -> KipHostView { KipHostView(state: state) }
    func updateNSView(_ view: KipHostView, context: Context) { view.set(state) }
}
